<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/includes/role_check.php';
require_role(['department']);
$department_id = (int)($_SESSION['department_id'] ?? 0);
$message = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['assign_complaint'])) {
    $complaint_id = (int)($_POST['complaint_id'] ?? 0);
    $officer_id = (int)($_POST['officer_id'] ?? 0);
    $remarks = trim($_POST['department_remarks'] ?? '');
    $check = $conn->prepare('SELECT id, user_id FROM complaints WHERE id = ? AND department_id = ?');
    $check->bind_param('ii', $complaint_id, $department_id); $check->execute(); $complaint = $check->get_result()->fetch_assoc(); $check->close();
    $valid = false;
    if ($complaint && $officer_id > 0) {
        $os = $conn->prepare("SELECT id FROM users WHERE id = ? AND role = 'officer' AND department_id = ? AND is_active = 1");
        $os->bind_param('ii', $officer_id, $department_id); $os->execute(); $valid = (bool)$os->get_result()->fetch_assoc(); $os->close();
    }
    if ($complaint && $valid) {
        $stmt = $conn->prepare("UPDATE complaints SET officer_id = ?, department_remarks = ?, status = CASE WHEN status = 'Pending' THEN 'In Progress' ELSE status END WHERE id = ? AND department_id = ?");
        $stmt->bind_param('isii', $officer_id, $remarks, $complaint_id, $department_id); $stmt->execute(); $stmt->close();
        $actor = (int)$_SESSION['user_id']; $action = 'Officer Assigned'; $desc = 'Department assigned the complaint to an officer.';
        $tl = $conn->prepare('INSERT INTO complaint_timeline (complaint_id,user_id,action,new_value,description) VALUES (?,?,?,?,?)'); $tl->bind_param('iisss', $complaint_id,$actor,$action,$officer_id,$desc); $tl->execute(); $tl->close();
        $n = $conn->prepare("INSERT INTO notifications (user_id, complaint_id, title, message, type) VALUES (?, ?, 'Complaint Assigned', 'Your complaint has been assigned to a complaint officer.', 'assignment')"); $n->bind_param('ii', $complaint['user_id'], $complaint_id); $n->execute(); $n->close();
        $message = 'Complaint assignment saved.';
    }
}
$status = $_GET['status'] ?? '';
$priority = $_GET['priority'] ?? '';
$search = trim($_GET['search'] ?? '');
$sql = "SELECT c.*, u.full_name AS user_name, u.email AS user_email, o.full_name AS officer_name FROM complaints c JOIN users u ON u.id=c.user_id LEFT JOIN users o ON o.id=c.officer_id WHERE c.department_id=?";
$types = 'i'; $params = [$department_id];
if (in_array($status, ['Pending','In Progress','Resolved','Rejected'], true)) { $sql .= ' AND c.status=?'; $types .= 's'; $params[] = $status; }
if (in_array($priority, ['Low','Medium','High','Critical'], true)) { $sql .= ' AND c.priority=?'; $types .= 's'; $params[] = $priority; }
if ($search !== '') { $sql .= ' AND (c.subject LIKE ? OR c.description LIKE ?)'; $types .= 'ss'; $like = "%$search%"; $params[]=$like; $params[]=$like; }
$sql .= ' ORDER BY FIELD(c.priority,"Critical","High","Medium","Low"), c.created_at DESC';
$stmt=$conn->prepare($sql); $stmt->bind_param($types, ...$params); $stmt->execute(); $complaints=$stmt->get_result()->fetch_all(MYSQLI_ASSOC); $stmt->close();
$os=$conn->prepare("SELECT id,full_name FROM users WHERE role='officer' AND department_id=? AND is_active=1 ORDER BY full_name"); $os->bind_param('i',$department_id); $os->execute(); $officers=$os->get_result()->fetch_all(MYSQLI_ASSOC); $os->close();
$stats=[]; $s=$conn->prepare('SELECT status,COUNT(*) total FROM complaints WHERE department_id=? GROUP BY status'); $s->bind_param('i',$department_id); $s->execute(); foreach($s->get_result() as $r) $stats[$r['status']]=(int)$r['total']; $s->close();
$ds=$conn->prepare('SELECT name FROM departments WHERE id=?'); $ds->bind_param('i',$department_id); $ds->execute(); $department_name=$ds->get_result()->fetch_assoc()['name'] ?? 'Department'; $ds->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($department_name)?> | Grievance Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="assets/css/style.css" rel="stylesheet"></head><body class="bg-light"><div class="d-flex min-vh-100"><?php include 'includes/sidebar.php'; ?><main class="flex-grow-1"><header class="bg-white border-bottom p-3 d-flex justify-content-between"><div><h4 class="mb-0">Department Dashboard</h4><small class="text-muted"><?=htmlspecialchars($department_name)?> · Scoped work queue</small></div><span class="text-muted"><i class="bi bi-person-circle me-1"></i><?=htmlspecialchars($_SESSION['user_name'])?></span></header><div class="container-fluid p-4"><?php if($message):?><div class="alert alert-success"><?=htmlspecialchars($message)?></div><?php endif;?><div class="row g-3 mb-4"><?php foreach([['Pending','warning','bi-hourglass-split'],['In Progress','info','bi-arrow-repeat'],['Resolved','success','bi-check-circle'],['Rejected','danger','bi-x-circle']] as $card):?><div class="col-6 col-xl-3"><div class="card border-0 shadow-sm h-100"><div class="card-body"><div class="d-flex justify-content-between"><span class="text-muted"><?=$card[0]?></span><i class="bi <?=$card[2]?> text-<?=$card[1]?>"></i></div><h2 class="mt-2 mb-0"><?= $stats[$card[0]] ?? 0 ?></h2></div></div></div><?php endforeach;?></div><div class="card border-0 shadow-sm"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-5"><input class="form-control" name="search" value="<?=htmlspecialchars($search)?>" placeholder="Search subject or description"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['Pending','In Progress','Resolved','Rejected'] as $v):?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="priority"><option value="">All priorities</option><?php foreach(['Low','Medium','High','Critical'] as $v):?><option <?=$priority===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100"><i class="bi bi-filter me-1"></i>Filter</button></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Complaint</th><th>Complainant</th><th>Priority</th><th>Status</th><th>Officer</th><th>Action</th></tr></thead><tbody><?php foreach($complaints as $c):?><tr><td><a href="view_complaint.php?id=<?=$c['id']?>" class="fw-semibold text-decoration-none"><?=htmlspecialchars($c['subject'])?></a><div class="small text-muted">#<?=$c['id']?> · <?=htmlspecialchars($c['category'])?></div></td><td><?=htmlspecialchars($c['user_name'])?><div class="small text-muted"><?=htmlspecialchars($c['user_email'])?></div></td><td><span class="badge text-bg-<?=priority_badge_class($c['priority'])?>"><?=$c['priority']?></span></td><td><span class="badge text-bg-<?=status_badge_class($c['status'])?>"><?=$c['status']?></span></td><td><?=htmlspecialchars($c['officer_name'] ?? 'Unassigned')?></td><td><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#assign<?=$c['id']?>"><i class="bi bi-person-plus me-1"></i>Assign</button><div class="modal fade" id="assign<?=$c['id']?>" tabindex="-1"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h5 class="modal-title">Assign #<?=$c['id']?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="complaint_id" value="<?=$c['id']?>"><label class="form-label">Complaint officer</label><select class="form-select mb-3" name="officer_id" required><option value="">Select officer</option><?php foreach($officers as $o):?><option value="<?=$o['id']?>" <?=$c['officer_id']==$o['id']?'selected':''?>><?=htmlspecialchars($o['full_name'])?></option><?php endforeach;?></select><label class="form-label">Departmental remarks</label><textarea class="form-control" name="department_remarks" rows="3"><?=htmlspecialchars($c['department_remarks'] ?? '')?></textarea></div><div class="modal-footer"><button class="btn btn-primary" name="assign_complaint">Save assignment</button></div></form></div></div></td></tr><?php endforeach;?><?php if(!$complaints):?><tr><td colspan="6" class="text-center text-muted py-5">No complaints match the selected filters.</td></tr><?php endif;?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
